import AVFoundation
import Foundation
import Combine

/// 音频引擎：节拍混音与后台播放
///
/// 关键设计：
/// - AVAudioSession: .playback + [.mixWithOthers]，与 Apple Music / Spotify / QQ音乐共存
/// - 独立 AVAudioEngine 混音，节拍音量与第三方音乐互不影响（音量通过 outputNode mixer 控制）
/// - DispatchSourceTimer（leeway 2ms）+ 0.15s 提前量调度，调度抖动远低于 50ms
/// - 后台保活：audio background mode 由 AVAudioSession .playback 持有；
///   静音节拍时挂静音循环播放器（低电量策略，可关）
/// - 左右脚：声像 + 音高 + 触觉强度三维区分
/// - 节拍渐入：每拍按 rampRate SPM/拍 平滑趋近目标
/// - 中断（来电/通知/Siri）：AVAudioSession.interruptionNotification 结束后恢复
@MainActor
final class AudioEngine: ObservableObject {

    @Published var isPlaying = false
    @Published var beatVolume: Float = 0.9 {
        didSet { mixer?.outputVolume = beatVolume }
    }
    @Published var sound: BeatSound = .click { didSet { rebuildBuffers() } }
    @Published var hapticsEnabled = true
    @Published var stereoFeetEnabled = true
    @Published var keepAliveWhenSilent = true
    @Published var isInterrupted = false

    /// 当前实际播放步频（渐入过程中 != targetSPM）
    @Published private(set) var currentSPM = 0
    var targetSPM = 170
    /// 每拍向目标靠近的 SPM 数（0 = 不渐入立即到位）
    var rampPerBeat = 0

    private let engine = AVAudioEngine()
    private var mixer: AVAudioMixerNode?
    private var buffers: SoundFactory.Buffer?
    private var haptics = HapticEngine()

    private var scheduler: DispatchSourceTimer?
    private var nextBeatTime: TimeInterval = 0      // hostTime 秒
    private var isRightFoot = false
    private var beatCounter = 0
    private var lastScheduledAt: TimeInterval = 0

    /// 静音保活播放器
    private var silencePlayer: AVAudioPlayerNode?
    private var silenceBuffer: AVAudioPCMBuffer?

    private var observers: [NSObjectProtocol] = []

    // MARK: - 生命周期

    init() {
        setupSession()
        setupEngine()
        rebuildBuffers()
        observeInterruptions()
        observeRouteChange()
    }

    deinit { observers.forEach { NotificationCenter.default.removeObserver($0) } }

    private func setupSession() {
        let session = AVAudioSession.sharedInstance()
        do {
            // .playback：锁屏/后台不中断；.mixWithOthers：与音乐 App 共存（不暂停对方）
            try session.setCategory(.playback,
                                    mode: .default,
                                    options: [.mixWithOthers, .allowBluetoothA2DP])
            try session.setPreferredIOBufferDuration(0.005) // 5ms 缓冲，降低端到端延迟
            try session.setPreferredSampleRate(SoundFactory.sampleRate)
            try session.setActive(true)
        } catch {
            #if DEBUG
            print("[AudioEngine] session setup failed: \(error)")
            #endif
        }
    }

    private func setupEngine() {
        let mixerNode = AVAudioMixerNode()
        engine.attach(mixerNode)
        engine.connect(mixerNode, to: engine.mainMixerNode, format: nil)
        mixerNode.outputVolume = beatVolume
        mixer = mixerNode

        // 静音循环 buffer（1s），保活用
        if let format = AVAudioFormat(standardFormatWithSampleRate: SoundFactory.sampleRate, channels: 2),
           let buf = AVAudioPCMBuffer(pcmFormat: format, frameCapacity: SoundFactory.sampleRate) {
            buf.frameLength = SoundFactory.sampleRate
            silenceBuffer = buf
            let node = AVAudioPlayerNode()
            engine.attach(node)
            engine.connect(node, to: engine.mainMixerNode, format: format)
            node.volume = 0
            silencePlayer = node
        }

        engine.prepare()
        do { try engine.start() } catch {
            #if DEBUG
            print("[AudioEngine] engine start failed: \(error)")
            #endif
        }
    }

    private func rebuildBuffers() {
        buffers = SoundFactory.makeBuffers(sound)
    }

    // MARK: - 播放控制

    func start(atSPM spm: Int, rampFrom: Int? = nil, rampPerBeat rate: Int = 0) {
        targetSPM = spm
        rampPerBeat = max(0, rate)
        currentSPM = rampFrom ?? spm
        isRightFoot = false
        beatCounter = 0

        setupSession()
        if !engine.isRunning { try? engine.start() }
        haptics.start()

        if keepAliveWhenSilent, let node = silencePlayer, let buf = silenceBuffer {
            node.scheduleBuffer(buf, at: nil, options: [.loops])
            if !node.isPlaying { node.play() }
        }

        let now = engineTime()
        nextBeatTime = now + 0.06
        lastScheduledAt = now
        isPlaying = true
        startScheduler()
    }

    func stop() {
        isPlaying = false
        scheduler?.cancel()
        scheduler = nil
        silencePlayer?.stop()
        haptics.stop()
        currentSPM = 0
    }

    func updateTarget(_ spm: Int) {
        // 训练中动态改步频：不中断播放，渐入速率决定跟手程度
        targetSPM = spm
        if rampPerBeat == 0 { currentSPM = spm }
    }

    /// 开始一段新的渐入（如阶段切换 / 自由跑中改目标）
    func ramp(to spm: Int, perBeat rate: Int) {
        targetSPM = spm
        rampPerBeat = max(0, rate)
        if rate == 0 { currentSPM = spm }
    }

    // MARK: - 调度器（节拍 < 50ms 延迟的核心）

    private func startScheduler() {
        let t = DispatchSource.makeTimerSource(queue: DispatchQueue(label: "com.temporun.scheduler",
                                                                    qos: .userInteractive))
        // 20Hz 检查 + 2ms leeway：每次只在窗口内提前 0.15s 排程，杜绝漂移
        t.schedule(deadline: .now() + .milliseconds(20),
                   repeating: .milliseconds(20),
                   leeway: .milliseconds(2))
        t.setEventHandler { [weak self] in
            // DispatchSource 回调在后台队列；引擎 API 本身线程安全
            self?.tick()
        }
        t.resume()
        scheduler = t
    }

    private func tick() {
        guard isPlaying else { return }
        let now = engineTime()
        let horizon = now + AppConstants.schedulerAhead

        // 提前 0.15s 把节拍塞进 player，实际发声由硬件时钟精确触发
        while nextBeatTime <= horizon {
            scheduleBeat(at: nextBeatTime)
            let interval = 60.0 / Double(max(1, currentSPM))
            nextBeatTime += interval
        }
    }

    private func scheduleBeat(at hostTimeSeconds: TimeInterval) {
        guard let mixer, let buffers else { return }
        let isRight = isRightFoot
        let node = AVAudioPlayerNode()
        engine.attach(node)
        engine.connect(node, to: mixer, format: buffers.right.format)

        let buffer = (isRight || !stereoFeetEnabled) ? buffers.right : buffers.left
        let avTime = AVAudioTime(hostTime: Self.hostTime(forSeconds: hostTimeSeconds))
        node.scheduleBuffer(buffer, at: avTime, options: []) { [weak self, weak node] in
            // 播放完毕后摘除节点，避免节点无限增长
            if let node { self?.engine.detach(node) }
        }
        if !node.isPlaying { node.play() }

        // 触觉：以音频发声时刻为准，提前量换算成相对 CHHapticTimeImmediate
        if hapticsEnabled {
            let offset = max(0, hostTimeSeconds - engineTime()) - AppConstants.hapticAhead
            let rel = max(0, offset)
            haptics.playFoot(isRight: isRight, relativeTime: rel)
        }

        isRightFoot.toggle()
        beatCounter += 1

        // 节拍渐入：每拍逼近目标（在后台线程更新值，UI 读取无所谓原子性）
        if rampPerBeat > 0, currentSPM != targetSPM {
            let dir = targetSPM > currentSPM ? 1 : -1
            let next = currentSPM + dir * rampPerBeat
            currentSPM = (dir > 0) ? min(next, targetSPM) : max(next, targetSPM)
        }
    }

    // MARK: - 时钟

    private func engineTime() -> TimeInterval {
        guard let nodeTime = engine.outputNode.lastRenderTime,
              let t = engine.outputNode.playerTime(forNodeTime: nodeTime) else {
            return CACurrentMediaTime()
        }
        return Double(t.sampleTime) / t.sampleRate
    }

    private static func hostTime(forSeconds s: TimeInterval) -> UInt64 {
        var tinfo = mach_timebase_info_data_t()
        mach_timebase_info(&tinfo)
        let nanos = UInt64(s * 1_000_000_000)
        return nanos * UInt64(tinfo.denom) / UInt64(tinfo.numer)
    }

    // MARK: - 中断与路由（来电 / 通知 / 闹钟 / Siri / 拔耳机）

    private func observeInterruptions() {
        let center = NotificationCenter.default
        observers.append(center.addObserver(
            forName: AVAudioSession.interruptionNotification, object: nil, queue: .main) { [weak self] note in
                guard let self, let info = note.userInfo,
                      let typeValue = info[AVAudioSessionInterruptionTypeKey] as? UInt,
                      let type = AVAudioSession.InterruptionType(rawValue: typeValue) else { return }
                switch type {
                case .began:
                    self.isInterrupted = true
                    self.scheduler?.suspend()
                    self.silencePlayer?.pause()
                case .ended:
                    // .shouldResume：第三方短暂混音（如导航）通常不带此标志，系统音频结束后我们自然继续
                    let options = AVAudioSession.InterruptionOptions(
                        rawValue: (info[AVAudioSessionInterruptionOptionKey] as? UInt) ?? 0)
                    guard options.contains(.shouldResume) else {
                        self.scheduler?.resume()
                        return
                    }
                    try? AVAudioSession.sharedInstance().setActive(true, options: [])
                    if !self.engine.isRunning { try? self.engine.start() }
                    self.silencePlayer?.play()
                    self.scheduler?.resume()
                    // 重置节拍基线，避免暂停期间堆积的调度时刻爆发
                    self.nextBeatTime = self.engineTime() + 0.06
                    self.isInterrupted = false
                @unknown default: break
                }
            })
    }

    private func observeRouteChange() {
        observers.append(NotificationCenter.default.addObserver(
            forName: AVAudioSession.routeChangeNotification, object: nil, queue: .main) { [weak self] note in
                guard let reasonValue = note.userInfo?[AVAudioSessionRouteChangeReasonKey] as? UInt,
                      let reason = AVAudioSession.RouteChangeReason(rawValue: reasonValue) else { return }
                switch reason {
                case .oldDeviceUnavailable:
                    // 拔出耳机：按 HIG 暂停，等待用户手动继续（避免公放）
                    self?.stop()
                case .newDeviceAvailable, .categoryChange, .override:
                    if self?.isPlaying == true,
                       let engine = self?.engine, !engine.isRunning {
                        try? engine.start()
                    }
                default: break
                }
            })
    }

    // MARK: - 媒体信息（锁屏显示）

    func updateNowPlaying(title: String, cadence: Int) {
        var info: [String: Any] = [
            MPMediaItemPropertyTitle: title,
            MPMediaItemPropertyArtist: "TempoRun",
            MPMediaItemPropertyPlaybackDuration: 0
        ]
        MPNowPlayingInfoCenter.default().nowPlayingInfo = info
        _ = cadence
    }
}

