@MainActor
final class CadencePreviewModel: ObservableObject {
    @Published var isPlaying = false
    var stereoFeet = true { didSet { audio.stereoFeetEnabled = stereoFeet } }
    var rampPerBeat = 2 { didSet { audio.rampPerBeat = rampPerBeat } }
    private let audio = AudioEngine()

    func toggle(target: Int, sound: BeatSound) {
        if isPlaying {
            audio.stop()
            isPlaying = false
        } else {
            audio.sound = sound
            audio.stereoFeetEnabled = stereoFeet
            audio.rampPerBeat = rampPerBeat
            audio.start(atSPM: target,
                        rampFrom: rampPerBeat > 0 ? max(60, target - 20) : target,
                        rampPerBeat: rampPerBeat)
            isPlaying = true
        }
    }
    func updateTarget(_ v: Int) { if isPlaying { audio.updateTarget(v) } }
    func setSound(_ s: BeatSound) {
        audio.sound = s
        if isPlaying { audio.stop(); audio.start(atSPM: audio.targetSPM) }
    }
    func stopIfOnlyPreview() { audio.stop(); isPlaying = false }
}

