        let now = Date()
        let entries = (0..<60).map { i in
            RunStatusEntry(date: now.addingTimeInterval(TimeInterval(i)),
                           state: RunCommands.currentState())
        }
        completion(Timeline(entries: entries, policy: .atEnd))
    }
}

