                    Toggle("左右脚交替提示（音色/声像/振动）", isOn: $preview.stereoFeet)
                        .card()
                    Toggle("节拍渐入（从当前步频平滑过渡）", isOn: $rampEnabled)
                        .card()
                        .onChange(of: rampEnabled) { _ in
                            preview.rampPerBeat = rampEnabled ? 2 : 0
                        }

                    Text("节拍与第三方音乐可同时播放，音量相互独立")
                        .font(.caption).foregroundColor(.secondary)
                        .multilineTextAlignment(.center)
                }
                .padding()
            }
            .background(Color(.systemGroupedBackground).ignoresSafeArea())
            .navigationTitle("步频器")
            .sheet(isPresented: $showNumberPad) {
                CadenceNumberInput(initial: target) { value in
                    target = value
                    preview.updateTarget(value)
                    save()
                    showNumberPad = false
                }
                .presentationDetents([.height(320)])
            }
            .onDisappear { preview.stopIfOnlyPreview() }
        }
    }

    private func save() {
        UserDefaults.standard.set(target, forKey: "targetCadence")
        UserDefaults.standard.set(sound.rawValue, forKey: "beatSound")
    }
}

/// 数字输入弹窗（第三种调节方式）
private struct CadenceNumberInput: View {
    @State var text: String
    let initial: Int
    let confirm: (Int) -> Void
    @Environment(\.dismiss) private var dismiss

    init(initial: Int, confirm: @escaping (Int) -> Void) {
        self.initial = initial
        self._text = State(initialValue: "\(initial)")
        self.confirm = confirm
    }

    var body: some View {
        VStack(spacing: 20) {
            Text("输入目标步频").font(.headline)
            TextField("60–240", text: $text)
                .keyboardType(.numberPad)
                .font(.system(size: 44, weight: .heavy, design: .rounded))
                .multilineTextAlignment(.center)
                .padding()
                .background(Color(.secondarySystemBackground), in: RoundedRectangle(cornerRadius: 14))
                .padding(.horizontal)

            HStack {
                Button("取消") { dismiss() }
                    .frame(maxWidth: .infinity).padding().background(Color(.tertiarySystemFill), in: RoundedRectangle(cornerRadius: 12))
                Button("确定") {
                    if let v = Int(text), AppConstants.cadenceRange.contains(v) { confirm(v) }
                }
                .disabled(Int(text).map { !AppConstants.cadenceRange.contains($0) } ?? true)
                .frame(maxWidth: .infinity).padding()
                .background(Color.accentColor, in: RoundedRectangle(cornerRadius: 12))
                .foregroundColor(.white)
            }
            .padding(.horizontal)
            Spacer()
        }
        .padding(.top, 32)
    }
}

/// 试听用的轻量 AudioEngine 包装
@MainActor
final class CadencePreviewModel: ObservableObject {
    @Published var isPlaying = false
    var stereoFeet = true { didSet { audio.stereoFeetEnabled = stereoFeet } }
    var rampPerBeat = 2 { didSet { audio.rampPerBeat = rampPerBeat } }
    private let audio = AudioEngine()

    func toggle(target: Int, sound: BeatSound) {
        if isPlaying {
            audio.stop()
            isPlaying = false
        } else {
            audio.sound = sound
            audio.stereoFeetEnabled = stereoFeet
            audio.rampPerBeat = rampPerBeat
            audio.start(atSPM: target,
                        rampFrom: rampPerBeat > 0 ? max(60, target - 20) : target,
                        rampPerBeat: rampPerBeat)
            isPlaying = true
        }
    }
    func updateTarget(_ v: Int) { if isPlaying { audio.updateTarget(v) } }
    func setSound(_ s: BeatSound) {
        audio.sound = s
        if isPlaying { audio.stop(); audio.start(atSPM: audio.targetSPM) }
    }
    func stopIfOnlyPreview() { audio.stop(); isPlaying = false }
}

