import Foundation

// MARK: - 枚举
enum TrainingType: String, Codable, CaseIterable, Identifiable {
    case free = "自由跑"
    case fixed = "定频跑"
    case interval = "间歇训练"
    case custom = "自定义计划"
    var id: String { rawValue }
    var icon: String {
        switch self {
        case .free: return "figure.run"
        case .fixed: return "metronome"
        case .interval: return "timer"
        case .custom: return "slider.horizontal.3"
        }
    }
}

enum StageType: String, Codable, CaseIterable, Identifiable {
    case warmup = "热身"
    case fast = "快跑"
    case slow = "慢跑"
    case cooldown = "冷身"
    case steady = "匀速"
    var id: String { rawValue }
    var colorName: String {
        switch self {
        case .warmup:   return "StageWarmup"
        case .fast:     return "StageFast"
        case .slow:     return "StageSlow"
        case .cooldown: return "StageCooldown"
        case .steady:   return "StageSteady"
        }
    }
}

enum Gender: String, Codable, CaseIterable {
    case male = "男", female = "女", other = "其他"
}

enum UnitSystem: String, Codable, CaseIterable {
    case metric = "公制", imperial = "英制"
}

// MARK: - 值类型（JSON 持久化 / Widget 共享安全）
struct TrackPoint: Codable, Hashable {
    let timestamp: Date
    let latitude: Double
    let longitude: Double
    let altitude: Double
    let horizontalAccuracy: Double
}

struct CadenceSample: Codable, Hashable, Identifiable {
    var id: Date { timestamp }
    let timestamp: Date
    let spm: Int
}

struct Split: Codable, Hashable, Identifiable {
    var id: Int { kilometer }
    let kilometer: Int
    let duration: TimeInterval
    let avgCadence: Int
    var pace: TimeInterval { duration } // 每公里秒数
}

/// 一条完整的跑步记录（与持久化实体解耦的值类型）
struct RunSummary: Codable, Hashable, Identifiable {
    var id: UUID = UUID()
    var userId: UUID?
    var startDate: Date = Date()
    var endDate: Date = Date()
    var duration: TimeInterval = 0
    var distanceMeters: Double = 0
    var avgCadence: Int = 0
    var maxCadence: Int = 0
    var calories: Double = 0
    var steps: Int = 0
    var trainingType: TrainingType = .free
    var planId: UUID?
    var note: String = ""
    var track: [TrackPoint] = []
    var cadenceSeries: [CadenceSample] = []
    var splits: [Split] = []

    var avgPace: TimeInterval { // sec/km
        distanceMeters > 50 ? duration / (distanceMeters / 1000) : 0
    }
    var distanceKilometers: Double { distanceMeters / 1000 }
}

struct UserProfile: Codable, Hashable {
    var id: UUID = UUID()
    var nickname: String = "跑者"
    var avatarData: Data?
    var gender: Gender = .other
    var age: Int?
    var weightKg: Double = 65
    var heightCm: Double = 170
    var unit: UnitSystem = .metric
    var language: String = Locale.preferredLanguages.first ?? "zh-Hans"
}

struct Stage: Codable, Hashable, Identifiable {
    var id: UUID = UUID()
    var type: StageType = .steady
    var targetCadence: Int = 170
    var duration: TimeInterval = 300   // 秒；0 表示按距离
    var distanceMeters: Double = 0
}

struct TrainingPlan: Codable, Hashable, Identifiable {
    var id: UUID = UUID()
    var userId: UUID?
    var name: String = ""
    var type: TrainingType = .custom
    var stages: [Stage] = []
}

import SwiftData
import Foundation

// SwiftData 需要 iOS 17+；工程最低支持 iOS 16，
// 因此所有 @Model 实体标注可用性，iOS 16 由 JSONHistoryStore 兜底（见 Services/Persistence）。

@available(iOS 17.0, *)
@Model
final class UserEntity {
    @Attribute(.unique) var id: UUID
    var nickname: String
    @Attribute(.externalStorage) var avatar: Data?
    var genderRaw: String
    var age: Int?
    var weightKg: Double
    var heightCm: Double
    var unitRaw: String
    var language: String

    init(id: UUID = UUID(), nickname: String, avatar: Data? = nil, genderRaw: String = "其他",
         age: Int? = nil, weightKg: Double = 65, heightCm: Double = 170,
         unitRaw: String = "公制", language: String = "zh-Hans") {
        self.id = id; self.nickname = nickname; self.avatar = avatar
        self.genderRaw = genderRaw; self.age = age
        self.weightKg = weightKg; self.heightCm = heightCm
        self.unitRaw = unitRaw; self.language = language
    }
}

@available(iOS 17.0, *)
@Model
final class RunRecordEntity {
    @Attribute(.unique) var id: UUID
    var userId: UUID?
    var startDate: Date
    var endDate: Date
    var duration: TimeInterval
    var distanceMeters: Double
    var avgCadence: Int
    var maxCadence: Int
    var calories: Double
    var steps: Int
    var trainingTypeRaw: String
    var planId: UUID?
    var note: String
    /// JSON: [TrackPoint]
    var trackData: Data?
    /// JSON: [CadenceSample]
    var cadenceSeriesData: Data?
    /// JSON: [Split]
    var splitsData: Data?

    init(id: UUID = UUID(), userId: UUID?, startDate: Date, endDate: Date,
         duration: TimeInterval, distanceMeters: Double, avgCadence: Int, maxCadence: Int,
         calories: Double, steps: Int, trainingTypeRaw: String, planId: UUID?, note: String,
         trackData: Data?, cadenceSeriesData: Data?, splitsData: Data?) {
        self.id = id; self.userId = userId
        self.startDate = startDate; self.endDate = endDate
        self.duration = duration; self.distanceMeters = distanceMeters
        self.avgCadence = avgCadence; self.maxCadence = maxCadence
        self.calories = calories; self.steps = steps
        self.trainingTypeRaw = trainingTypeRaw; self.planId = planId; self.note = note
        self.trackData = trackData; self.cadenceSeriesData = cadenceSeriesData
        self.splitsData = splitsData
    }
}

@available(iOS 17.0, *)
@Model
final class TrainingPlanEntity {
    @Attribute(.unique) var id: UUID
    var userId: UUID?
    var name: String
    var typeRaw: String
    /// JSON: [Stage]
    var stagesData: Data?

    init(id: UUID = UUID(), userId: UUID?, name: String, typeRaw: String, stagesData: Data?) {
        self.id = id; self.userId = userId; self.name = name
        self.typeRaw = typeRaw; self.stagesData = stagesData
    }
}

// MARK: - Entity <-> 值类型映射
@available(iOS 17.0, *)
extension RunRecordEntity {
    convenience init(_ r: RunSummary) {
        self.init(id: r.id, userId: r.userId,
                  startDate: r.startDate, endDate: r.endDate,
                  duration: r.duration, distanceMeters: r.distanceMeters,
                  avgCadence: r.avgCadence, maxCadence: r.maxCadence,
                  calories: r.calories, steps: r.steps,
                  trainingTypeRaw: r.trainingType.rawValue, planId: r.planId, note: r.note,
                  trackData: try? JSONEncoder().encode(r.track),
                  cadenceSeriesData: try? JSONEncoder().encode(r.cadenceSeries),
                  splitsData: try? JSONEncoder().encode(r.splits))
    }

    func summary() -> RunSummary {
        var r = RunSummary(
            id: id, userId: userId, startDate: startDate, endDate: endDate,
            duration: duration, distanceMeters: distanceMeters,
            avgCadence: avgCadence, maxCadence: maxCadence, calories: calories,
            steps: steps,
            trainingType: TrainingType(rawValue: trainingTypeRaw) ?? .free,
            planId: planId, note: note)
        if let d = trackData { r.track = (try? JSONDecoder().decode([TrackPoint].self, from: d)) ?? [] }
        if let d = cadenceSeriesData { r.cadenceSeries = (try? JSONDecoder().decode([CadenceSample].self, from: d)) ?? [] }
        if let d = splitsData { r.splits = (try? JSONDecoder().decode([Split].self, from: d)) ?? [] }
        return r
    }
}

