            return await finishPurchase(product: product)
        }
        return await finishPurchase(product: product)
    }

    @discardableResult
    func purchase(_ product: Product) async -> PurchaseResult {
        await finishPurchase(product: product)
    }

    private func finishPurchase(product: Product) async -> PurchaseResult {
