// MARK: 恢复购买

@discardableResult
func restore() async -> Bool {
    var found = false
    for await result in Transaction.currentEntitlements {
        if case .verified(let transaction) = result {
            found = true
            await apply(transaction: transaction)
        }
    }
    if !found { await downgradeToFree() }
    didRestore = true
    return found
}

